{"action": "write_file", "file_content": "/*
 * KDP-Safe EPUB CSS Template
 * Complies with Amazon Kindle Publishing Guidelines 2025.1
 *
 * CRITICAL RULES:
 * - NO ::before / ::after pseudo-elements (not supported in KF8)
 * - NO counter-increment / counter-reset (not supported in KF8)
 * - NO ::first-letter / ::first-line (not supported in KF8)
 * - NO :nth-child / :first-child / :last-child / :visited (not supported)
 * - NO <img> selector (use class-based selectors instead)
 * - NO <script> tags allowed anywhere
 * - NO fixed font-size/color on body <p> (breaks Enhanced Typesetting)
 * - Use relative units (em, %) for body text, not pt/px
 * - @font-face IS supported — embed custom fonts with proper licensing
 */

/* --- Base --- */
body {
  font-family: serif;
  /* DO NOT set font-size or color here — let Enhanced Typesetting apply reader prefs */
  line-height: 1.5;
  margin: 0;
  padding: 0;
  widows: 2;
  orphans: 2;
}

/* --- Headings --- */
h1, h2, h3, h4, h5, h6 {
  font-family: sans-serif;
  font-weight: bold;
  text-align: center;
  /* Safe to style headings with specific sizes */
  /* Use pt for headings — these are styled elements */
}

h1 {
  font-size: 1.6em;
  margin: 2em 0 1em 0;
  page-break-before: always;
}

h2 {
  font-size: 1.3em;
  margin: 1.5em 0 0.8em 0;
}

h3 {
  font-size: 1.1em;
  margin: 1.2em 0 0.6em 0;
}

/* --- Paragraphs --- */
p {
  text-indent: 1.5em;
  margin: 0;
  padding: 0;
}

/* No indent on first paragraph after heading */
h1 + p, h2 + p, h3 + p, h4 + p, h5 + p, h6 + p {
  text-indent: 0;
}

/* Drop caps — use span with class, NOT ::first-letter */
.dropcap {
  float: left;
  font-size: 3em;
  line-height: 0.8;
  margin: 0 0.1em -0.1em 0;
}

/* --- Chapter Titles --- */
.chapter-title {
  font-family: sans-serif;
  font-size: 1.6em;
  font-weight: bold;
  text-align: center;
  margin: 0 0 1.5em 0;
  page-break-before: always;
}

/* --- Images --- */
/* Use class selector, NOT the <img> element selector (unsupported in KF8) */
.image-inline {
  max-width: 100%;
  height: auto;
  display: block;
  margin: 1em auto;
}

.image-full-page {
  max-width: 100%;
  height: auto;
  display: block;
  margin: 0 auto;
  page-break-before: always;
  page-break-after: always;
}

.image-left {
  float: left;
  max-width: 45%;
  margin: 0.5em 1em 0.5em 0;
}

.image-right {
  float: right;
  max-width: 45%;
  margin: 0.5em 0 0.5em 1em;
}

/* --- Tables --- */
table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9em;
  margin: 1em 0;
  table-layout: fixed;
  word-wrap: break-word;
}

th {
  font-family: sans-serif;
  font-weight: bold;
  border: 1px solid #ccc;
  padding: 0.3em 0.5em;
  background-color: #f0f0f0;
}

td {
  border: 1px solid #ccc;
  padding: 0.3em 0.5em;
}

caption {
  font-family: sans-serif;
  font-weight: bold;
  margin-bottom: 0.5em;
  text-align: center;
}

/* --- Blockquotes --- */
blockquote {
  margin: 1em 1.5em;
  font-style: italic;
  color: #555; /* Color OK for styled elements */
}

/* --- Lists --- */
ul, ol {
  margin: 0.5em 0;
  padding-left: 2em;
}

li {
  margin: 0.2em 0;
}

/* --- Horizontal Rule --- */
hr {
  border: none;
  border-top: 1px solid #ccc;
  margin: 1.5em 0;
  width: 30%;
}

/* --- Code / Pre --- */
code {
  font-family: monospace;
  font-size: 0.9em;
}

pre {
  font-family: monospace;
  font-size: 0.85em;
  margin: 1em 0;
  white-space: pre-wrap;
}

/* --- Cover Page --- */
.cover-page {
  page-break-before: always;
  page-break-after: always;
  text-align: center;
}

/* --- Front Matter --- */
.front-matter {
  page-break-after: always;
}

/* --- Back Matter / Last Page --- */
.last-page {
  page-break-before: always;
  text-align: center;
  font-style: italic;
}

/* --- Footnotes --- */
.footnote {
  font-size: 0.85em;
  border-top: 1px solid #ccc;
  margin-top: 1em;
  padding-top: 0.5em;
}

/* Media Queries — Amazon-specific (supported) */
@media amzn-kf8 {
  /* Kindle Format 8 specific overrides */
  body {
    line-height: 1.4;
  }
}

@media amzn-mobi {
  /* Kindle Mobi specific overrides */
  body {
    font-family: serif;
  }
}
